---

## The Shape of Every Function

```rust
/// One-line doc explaining WHAT, not HOW.
///
/// # Errors
/// Returns `FooError::Bar` when the input is invalid.
const fn frobnicate<'a>(
    arena: &'a Bump,        // explicit allocator when arena is in play
    input: &[u8],           // borrow, not owned
    output: &mut [u8],      // caller-provided buffer
) -> Result<&'a Frob, FrobError> {
    // ...
}
```

**Why this shape:** the caller sees every cost. Allocation scope is the arena's lifetime. Input is borrowed. Output buffer is caller-owned. Error is typed. The compiler enforces all of it.

---

## Activation

This skill activates whenever you are writing or modifying any `.rs` file or `Cargo.toml`. One-off scripts get the strict treatment too — `rust-script` + the same lints, the same gates. Details → [one-liners.md](one-liners.md).

**The promise:** production hygiene with throwaway ergonomics. Explicit allocation, compile-time proof, zero hidden cost, and **agent-proof safety at any volume**.

//! Native notification domain.
//!
//! Rust decides *how* to talk to the OS safely; the frontend decides *whether*
//! an application event should notify. React state, active-tab knowledge, and
//! user-event dedupe deliberately stay out of this module.

pub mod audio;
pub mod model;
pub mod permission;
pub mod service;

pub use audio::*;
pub use model::*;
pub use permission::*;
pub use service::*;

/// Open the OS notification settings for rorca.
///
/// Deliberately narrow: the target is fixed per platform and never accepted
/// from the frontend, so this cannot become a general URI-open primitive.
pub fn open_system_notification_settings() -> OpenSystemSettingsResult {
    #[cfg(target_os = "macos")]
    {
        // On macOS, running `open x-apple.systempreferences:...` or opening System Settings
        // when the app is unbundled or unnotified causes unwanted disruptive UI popups.
        // Explicitly report unsupported to avoid unexpected System Settings window launches.
        OpenSystemSettingsResult {
            opened: false,
            reason: Some("opening system settings is disabled in dev/standalone mode".into()),
        }
    }

    #[cfg(target_os = "windows")]
    {
        if run_opener("cmd", &["/C", "start", "", "ms-settings:notifications"]) {
            return OpenSystemSettingsResult {
                opened: true,
                reason: None,
            };
        }
        OpenSystemSettingsResult {
            opened: false,
            reason: Some("could not open Windows notification settings".into()),
        }
    }

    // Linux desktop environments have no single notification settings target.
    #[cfg(not(any(target_os = "macos", target_os = "windows")))]
    {
        OpenSystemSettingsResult {
            opened: false,
            reason: Some("unsupported".into()),
        }
    }
}

#[cfg(any(target_os = "macos", target_os = "windows"))]
#[allow(dead_code)]
fn run_opener(program: &str, args: &[&str]) -> bool {
    std::process::Command::new(program)
        .args(args)
        .status()
        .map(|status| status.success())
        .unwrap_or(false)
}

#[cfg(test)]
mod tests;

//! Pure notification domain types and content policy.
//!
//! Nothing in this module touches the OS. Content formatting, sanitization,
//! permission normalization, and audio request validation all live here so
//! they can be unit tested without displaying real notifications or opening
//! an audio device.

use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

/// Maximum rendered length of a notification title.
pub const MAX_TITLE_LEN: usize = 80;
/// Maximum rendered length of a notification body.
pub const MAX_BODY_LEN: usize = 160;
/// Upper bound for a custom notification sound file.
pub const MAX_AUDIO_FILE_BYTES: u64 = 20 * 1024 * 1024;
/// Audio extensions matching the enabled `rodio` decoder feature set.
pub const SUPPORTED_AUDIO_EXTENSIONS: &[&str] =
    &["wav", "mp3", "flac", "ogg", "oga", "m4a", "mp4", "aac"];

/// Application event that asked for a notification.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum NotificationSource {
    AgentTaskComplete,
    TerminalBell,
    #[default]
    Test,
}

/// Why a dispatch did not result in a submitted notification.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum NotificationDispatchReason {
    PermissionRequired,
    BlockedBySystem,
    Unsupported,
    BackendError,
}

/// Frontend request to raise a native notification.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DispatchNotificationRequest {
    pub source: NotificationSourceField,
    #[serde(default)]
    pub notification_id: Option<String>,
    #[serde(default)]
    pub workspace_label: Option<String>,
    #[serde(default)]
    pub worktree_label: Option<String>,
    #[serde(default)]
    pub terminal_title: Option<String>,
    #[serde(default)]
    pub agent_label: Option<String>,
}

/// `source` defaults to `test` so a malformed payload cannot silently
/// impersonate an agent-completion notification.
pub type NotificationSourceField = NotificationSource;

/// Outcome of a dispatch attempt.
///
/// `submitted` means the request passed preflight and was handed to the
/// native backend. It never claims the user actually saw a banner: Focus
/// modes and notification-center policy are outside rorca's visibility.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DispatchNotificationResult {
    pub submitted: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reason: Option<NotificationDispatchReason>,
}

impl DispatchNotificationResult {
    pub fn submitted() -> Self {
        Self {
            submitted: true,
            reason: None,
        }
    }

    pub fn rejected(reason: NotificationDispatchReason) -> Self {
        Self {
            submitted: false,
            reason: Some(reason),
        }
    }
}

/// Rendered, sanitized notification text ready for the native backend.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct NotificationContent {
    pub title: String,
    pub body: String,
}

/// Host platform, reported so the UI can explain platform differences.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum NotificationPlatform {
    Macos,
    Windows,
    Linux,
    Other,
}

impl NotificationPlatform {
    pub fn current() -> Self {
        #[cfg(target_os = "macos")]
        {
            Self::Macos
        }
        #[cfg(target_os = "windows")]
        {
            Self::Windows
        }
        #[cfg(target_os = "linux")]
        {
            Self::Linux
        }
        #[cfg(not(any(target_os = "macos", target_os = "windows", target_os = "linux")))]
        {
            Self::Other
        }
    }
}

/// Normalized authorization state across platforms.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum NotificationAuthorization {
    NotDetermined,
    Authorized,
    Denied,
    Provisional,
    Unknown,
}

/// Cross-platform permission status.
///
/// `authoritative` distinguishes a real OS query (macOS `UNNotificationSettings`)
/// from a best-effort assumption. Tauri's desktop `permission_state()` always
/// returns `Granted`, so it is never used as the source of truth here.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct NotificationPermissionStatusDto {
    pub platform: NotificationPlatform,
    pub supported: bool,
    pub authorization: NotificationAuthorization,
    pub alerts_enabled: Option<bool>,
    pub sounds_enabled: Option<bool>,
    pub requested: bool,
    pub authoritative: bool,
    pub can_open_settings: bool,
}

impl NotificationPermissionStatusDto {
    /// Non-authoritative status for platforms without a real permission query.
    pub fn non_authoritative(platform: NotificationPlatform, can_open_settings: bool) -> Self {
        Self {
            platform,
            supported: true,
            authorization: NotificationAuthorization::Unknown,
            alerts_enabled: None,
            sounds_enabled: None,
            requested: false,
            authoritative: false,
            can_open_settings,
        }
    }

    pub fn unsupported(platform: NotificationPlatform) -> Self {
        Self {
            platform,
            supported: false,
            authorization: NotificationAuthorization::Unknown,
            alerts_enabled: None,
            sounds_enabled: None,
            requested: false,
            authoritative: false,
            can_open_settings: false,
        }
    }

    /// True when an authoritative query proves the OS will drop notifications.
    pub fn is_blocked(&self) -> bool {
        self.authoritative && self.authorization == NotificationAuthorization::Denied
    }

    /// True when macOS has never been asked and no implicit prompt may occur.
    pub fn needs_permission_request(&self) -> bool {
        self.authoritative && self.authorization == NotificationAuthorization::NotDetermined
    }
}

/// Result of an explicit permission request.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct NotificationPermissionRequestDto {
    /// Whether the platform reported the request itself as granted.
    pub granted: bool,
    /// Status re-queried after the request resolved.
    pub status: NotificationPermissionStatusDto,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
}

/// Probe outcome describing notification readiness.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum NotificationProbeOutcome {
    Submitted,
    Ready,
    PermissionRequired,
    BlockedBySystem,
    Unsupported,
    Failed,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct NotificationProbeResult {
    pub outcome: NotificationProbeOutcome,
    pub status: NotificationPermissionStatusDto,
    /// True only when a visible test notification was actually submitted.
    pub test_submitted: bool,
}

/// Why a custom sound did not play.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum PlaySoundReason {
    NotFound,
    UnsupportedFormat,
    FileTooLarge,
    DecodeFailed,
    NoOutputDevice,
    Deduped,
    BackendError,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PlaySoundResult {
    pub played: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reason: Option<PlaySoundReason>,
}

impl PlaySoundResult {
    pub fn played() -> Self {
        Self {
            played: true,
            reason: None,
        }
    }

    pub fn failed(reason: PlaySoundReason) -> Self {
        Self {
            played: false,
            reason: Some(reason),
        }
    }
}

/// Audio file chosen through the native picker.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PickedAudioFile {
    pub path: PathBuf,
    pub display_name: String,
}

/// Result of asking the OS to open its notification settings.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct OpenSystemSettingsResult {
    pub opened: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reason: Option<String>,
}

// ---------------------------------------------------------------------------
// Content policy
// ---------------------------------------------------------------------------

/// Strip control characters and collapse pathological whitespace.
///
/// Terminal titles and agent labels are attacker-adjacent input: they can
/// carry escape sequences, newlines, or padding designed to spoof notification
/// text. Everything below `0x20` plus DEL and the Unicode line separators is
/// replaced by a space, then runs of whitespace collapse to one space.
pub fn sanitize_text(raw: &str) -> String {
    let mut out = String::with_capacity(raw.len());
    let mut pending_space = false;

    for ch in raw.chars() {
        let is_blank = ch.is_control()
            || ch.is_whitespace()
            || matches!(ch, '\u{2028}' | '\u{2029}' | '\u{feff}');

        if is_blank {
            pending_space = !out.is_empty();
            continue;
        }

        if pending_space {
            out.push(' ');
            pending_space = false;
        }
        out.push(ch);
    }

    out
}

/// Truncate on a character boundary, appending an ellipsis when shortened.
pub fn truncate_text(text: &str, max_len: usize) -> String {
    if text.chars().count() <= max_len {
        return text.to_string();
    }
    if max_len == 0 {
        return String::new();
    }

    // Reserve one character for the ellipsis.
    let keep = max_len.saturating_sub(1);
    let mut out: String = text.chars().take(keep).collect();
    while out.ends_with(' ') {
        out.pop();
    }
    out.push('\u{2026}');
    out
}

fn clean_field(value: Option<&str>) -> Option<String> {
    let cleaned = sanitize_text(value?);
    if cleaned.is_empty() {
        None
    } else {
        Some(cleaned)
    }
}

/// Render final notification text for a dispatch request.
///
/// Deliberately conservative: no shell output, no agent prompt text, and no
/// absolute paths. Native notifications can appear on a lock screen, so only
/// short display labels the user already chose are included.
pub fn format_notification(request: &DispatchNotificationRequest) -> NotificationContent {
    let agent = clean_field(request.agent_label.as_deref());
    let worktree = clean_field(request.worktree_label.as_deref());
    let workspace = clean_field(request.workspace_label.as_deref());
    let terminal = clean_field(request.terminal_title.as_deref());

    let (title, body) = match request.source {
        NotificationSource::AgentTaskComplete => {
            let title = match agent {
                Some(agent) => format!("{agent} finished"),
                None => "Agent finished".to_string(),
            };
            let body = worktree
                .or(workspace)
                .unwrap_or_else(|| "Task complete".to_string());
            (title, body)
        }
        NotificationSource::TerminalBell => {
            let title = "Terminal needs attention".to_string();
            let location = worktree.or(workspace);
            let body = match (location, terminal) {
                (Some(location), Some(terminal)) => format!("{location} \u{b7} {terminal}"),
                (Some(location), None) => location,
                (None, Some(terminal)) => terminal,
                (None, None) => "A terminal rang the bell".to_string(),
            };
            (title, body)
        }
        NotificationSource::Test => (
            "Ferryx notifications are working".to_string(),
            "Test notification".to_string(),
        ),
    };

    NotificationContent {
        title: truncate_text(&title, MAX_TITLE_LEN),
        body: truncate_text(&body, MAX_BODY_LEN),
    }
}

// ---------------------------------------------------------------------------
// Audio validation
// ---------------------------------------------------------------------------

/// Convert a frontend volume percentage to a linear gain.
///
/// Accepts `0..=100`; anything outside (including NaN) clamps into range so a
/// malformed setting can never produce a deafening or negative gain.
pub fn normalize_volume(percent: f32) -> f32 {
    if percent.is_nan() {
        return 0.0;
    }
    (percent / 100.0).clamp(0.0, 1.0)
}

/// True when the extension matches an enabled decoder.
pub fn is_supported_audio_extension(path: &Path) -> bool {
    path.extension()
        .and_then(|ext| ext.to_str())
        .map(|ext| {
            let lower = ext.to_ascii_lowercase();
            SUPPORTED_AUDIO_EXTENSIONS.contains(&lower.as_str())
        })
        .unwrap_or(false)
}

/// Validate a custom sound path before any decoding is attempted.
///
/// Returns the canonicalized path so playback never follows a path that
/// changed between validation and open.
pub fn validate_audio_path(path: &Path) -> Result<PathBuf, PlaySoundReason> {
    if !is_supported_audio_extension(path) {
        return Err(PlaySoundReason::UnsupportedFormat);
    }

    let canonical = path.canonicalize().map_err(|_| PlaySoundReason::NotFound)?;

    let metadata = canonical
        .metadata()
        .map_err(|_| PlaySoundReason::NotFound)?;

    if !metadata.is_file() {
        return Err(PlaySoundReason::NotFound);
    }
    if metadata.len() > MAX_AUDIO_FILE_BYTES {
        return Err(PlaySoundReason::FileTooLarge);
    }

    Ok(canonical)
}

/// Display name for a picked file, falling back to the full path string.
pub fn audio_display_name(path: &Path) -> String {
    path.file_name()
        .and_then(|name| name.to_str())
        .map(|name| name.to_string())
        .unwrap_or_else(|| path.to_string_lossy().to_string())
}

//! Notification dispatch orchestration.
//!
//! The service owns preflight and submission policy. Both the OS permission
//! query and the native submitter sit behind traits so command-level behavior
//! can be tested without ever displaying a real notification.

use super::model::{
    format_notification, DispatchNotificationRequest, DispatchNotificationResult,
    NotificationContent, NotificationDispatchReason, NotificationPermissionRequestDto,
    NotificationPermissionStatusDto, NotificationProbeOutcome, NotificationProbeResult,
    NotificationSource,
};
use super::permission::{platform_permission_provider, NotificationPermissionProvider};

/// Seam over the native notification backend.
///
/// Keeping submission behind a trait allows a fake backend in tests and a
/// future platform-specific silent adapter without changing the IPC contract.
pub trait NativeNotificationBackend: Send + Sync {
    fn submit(&self, content: &NotificationContent) -> Result<(), String>;
}

/// Preflight decision made before any submission is attempted.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PreflightDecision {
    Submit,
    Reject(NotificationDispatchReason),
}

/// Decide whether a dispatch may proceed for a given permission status.
///
/// Only an authoritative query can block: a non-authoritative `unknown` (every
/// current Windows/Linux build) is allowed through so those platforms keep
/// working, while macOS `denied`/`not-determined` short-circuit before the
/// backend can claim a bogus success.
pub fn preflight(status: &NotificationPermissionStatusDto) -> PreflightDecision {
    if !status.supported {
        return PreflightDecision::Reject(NotificationDispatchReason::Unsupported);
    }
    if status.is_blocked() {
        return PreflightDecision::Reject(NotificationDispatchReason::BlockedBySystem);
    }
    if status.needs_permission_request() {
        // Never prompt implicitly: the UI must ask via an explicit user action.
        return PreflightDecision::Reject(NotificationDispatchReason::PermissionRequired);
    }
    PreflightDecision::Submit
}

/// Notification domain service.
pub struct NotificationService {
    permissions: Box<dyn NotificationPermissionProvider>,
    backend: Box<dyn NativeNotificationBackend>,
}

impl NotificationService {
    pub fn new(
        permissions: Box<dyn NotificationPermissionProvider>,
        backend: Box<dyn NativeNotificationBackend>,
    ) -> Self {
        Self {
            permissions,
            backend,
        }
    }

    /// Service wired to the real platform permission provider.
    pub fn with_platform_permissions(backend: Box<dyn NativeNotificationBackend>) -> Self {
        Self::new(platform_permission_provider(), backend)
    }

    pub fn permission_status(&self) -> NotificationPermissionStatusDto {
        self.permissions.status()
    }

    /// Explicit, user-initiated authorization request.
    pub fn request_permission(&self) -> NotificationPermissionRequestDto {
        self.permissions.request()
    }

    /// Format, preflight, and submit one notification.
    pub fn dispatch(&self, request: &DispatchNotificationRequest) -> DispatchNotificationResult {
        let status = self.permissions.status();
        if let PreflightDecision::Reject(reason) = preflight(&status) {
            return DispatchNotificationResult::rejected(reason);
        }

        let content = format_notification(request);
        match self.backend.submit(&content) {
            Ok(()) => DispatchNotificationResult::submitted(),
            Err(error) => {
                tracing::warn!("native notification submission failed: {error}");
                DispatchNotificationResult::rejected(NotificationDispatchReason::BackendError)
            }
        }
    }

    /// Report readiness, optionally submitting one visible test notification.
    ///
    /// Reports `submitted`, never `visibly-delivered`: Focus and
    /// Do-Not-Disturb can suppress a banner with no signal back to rorca.
    pub fn probe_delivery(&self, send_test: bool) -> NotificationProbeResult {
        let status = self.permissions.status();

        let outcome = match preflight(&status) {
            PreflightDecision::Reject(NotificationDispatchReason::BlockedBySystem) => {
                NotificationProbeOutcome::BlockedBySystem
            }
            PreflightDecision::Reject(NotificationDispatchReason::PermissionRequired) => {
                NotificationProbeOutcome::PermissionRequired
            }
            PreflightDecision::Reject(NotificationDispatchReason::Unsupported) => {
                NotificationProbeOutcome::Unsupported
            }
            PreflightDecision::Reject(NotificationDispatchReason::BackendError) => {
                NotificationProbeOutcome::Failed
            }
            PreflightDecision::Submit => NotificationProbeOutcome::Ready,
        };

        if outcome != NotificationProbeOutcome::Ready || !send_test {
            return NotificationProbeResult {
                outcome,
                status,
                test_submitted: false,
            };
        }

        let content = format_notification(&DispatchNotificationRequest {
            source: NotificationSource::Test,
            ..Default::default()
        });

        match self.backend.submit(&content) {
            Ok(()) => NotificationProbeResult {
                outcome: NotificationProbeOutcome::Submitted,
                status,
                test_submitted: true,
            },
            Err(error) => {
                tracing::warn!("notification probe submission failed: {error}");
                NotificationProbeResult {
                    outcome: NotificationProbeOutcome::Failed,
                    status,
                    test_submitted: false,
                }
            }
        }
    }
}

impl std::fmt::Debug for NotificationService {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("NotificationService")
            .finish_non_exhaustive()
    }
}

#[cfg(test)]
pub(crate) mod test_support {
    use super::*;
    use crate::notification::model::{NotificationAuthorization, NotificationPlatform};
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::{Arc, Mutex};

    /// Permission provider returning a scripted status.
    pub struct FakePermissionProvider {
        pub status: NotificationPermissionStatusDto,
        pub request_calls: Arc<AtomicUsize>,
    }

    impl FakePermissionProvider {
        pub fn new(status: NotificationPermissionStatusDto) -> Self {
            Self {
                status,
                request_calls: Arc::new(AtomicUsize::new(0)),
            }
        }
    }

    impl NotificationPermissionProvider for FakePermissionProvider {
        fn status(&self) -> NotificationPermissionStatusDto {
            self.status.clone()
        }

        fn request(&self) -> NotificationPermissionRequestDto {
            self.request_calls.fetch_add(1, Ordering::SeqCst);
            NotificationPermissionRequestDto {
                granted: self.status.authorization == NotificationAuthorization::Authorized,
                status: self.status.clone(),
                error: None,
            }
        }
    }

    /// Backend recording submissions instead of showing notifications.
    #[derive(Default)]
    pub struct FakeBackend {
        pub submissions: Mutex<Vec<NotificationContent>>,
        pub fail_with: Option<String>,
    }

    impl FakeBackend {
        pub fn failing(message: &str) -> Self {
            Self {
                submissions: Mutex::new(Vec::new()),
                fail_with: Some(message.to_string()),
            }
        }

        pub fn count(&self) -> usize {
            self.submissions.lock().expect("submissions lock").len()
        }

        pub fn first_title(&self) -> Option<String> {
            self.submissions
                .lock()
                .expect("submissions lock")
                .first()
                .map(|content| content.title.clone())
        }

        pub fn first_body(&self) -> Option<String> {
            self.submissions
                .lock()
                .expect("submissions lock")
                .first()
                .map(|content| content.body.clone())
        }
    }

    impl NativeNotificationBackend for Arc<FakeBackend> {
        fn submit(&self, content: &NotificationContent) -> Result<(), String> {
            if let Some(error) = &self.fail_with {
                return Err(error.clone());
            }
            self.submissions
                .lock()
                .expect("submissions lock")
                .push(content.clone());
            Ok(())
        }
    }

    /// Authoritative macOS-shaped status for a given authorization value.
    pub fn macos_status(
        authorization: NotificationAuthorization,
    ) -> NotificationPermissionStatusDto {
        NotificationPermissionStatusDto {
            platform: NotificationPlatform::Macos,
            supported: true,
            authorization,
            alerts_enabled: Some(authorization == NotificationAuthorization::Authorized),
            sounds_enabled: Some(authorization == NotificationAuthorization::Authorized),
            requested: authorization != NotificationAuthorization::NotDetermined,
            authoritative: true,
            can_open_settings: true,
        }
    }

    /// Service backed entirely by fakes.
    pub fn service_with(
        status: NotificationPermissionStatusDto,
        backend: Arc<FakeBackend>,
    ) -> NotificationService {
        NotificationService::new(
            Box::new(FakePermissionProvider::new(status)),
            Box::new(backend),
        )
    }
}

#[cfg(test)]
mod tests {
    use super::test_support::*;
    use super::*;
    use crate::notification::model::{NotificationAuthorization, NotificationPlatform};
    use std::sync::atomic::Ordering;
    use std::sync::Arc;

    fn agent_request() -> DispatchNotificationRequest {
        DispatchNotificationRequest {
            source: NotificationSource::AgentTaskComplete,
            agent_label: Some("Claude".into()),
            worktree_label: Some("feat/login".into()),
            ..Default::default()
        }
    }

    #[test]
    fn authorized_status_submits_exactly_one_notification() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        let result = service.dispatch(&agent_request());

        assert!(result.submitted);
        assert!(result.reason.is_none());
        assert_eq!(backend.count(), 1);
        assert_eq!(backend.first_title().as_deref(), Some("Claude finished"));
        assert_eq!(backend.first_body().as_deref(), Some("feat/login"));
    }

    #[test]
    fn denied_macos_status_blocks_before_submitting() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Denied),
            Arc::clone(&backend),
        );

        let result = service.dispatch(&agent_request());

        assert!(!result.submitted);
        assert_eq!(
            result.reason,
            Some(NotificationDispatchReason::BlockedBySystem)
        );
        // Critical: the backend must never be reached when the OS denied us.
        assert_eq!(backend.count(), 0);
    }

    #[test]
    fn not_determined_returns_permission_required_without_implicit_prompt() {
        let backend = Arc::new(FakeBackend::default());
        let provider =
            FakePermissionProvider::new(macos_status(NotificationAuthorization::NotDetermined));
        let request_calls = Arc::clone(&provider.request_calls);
        let service = NotificationService::new(Box::new(provider), Box::new(Arc::clone(&backend)));

        let result = service.dispatch(&agent_request());

        assert_eq!(
            result.reason,
            Some(NotificationDispatchReason::PermissionRequired)
        );
        assert_eq!(backend.count(), 0);
        // A background event must never trigger a permission prompt.
        assert_eq!(request_calls.load(Ordering::SeqCst), 0);
    }

    #[test]
    fn backend_failure_is_reported_as_a_structured_reason() {
        let backend = Arc::new(FakeBackend::failing("dbus unavailable"));
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        let result = service.dispatch(&agent_request());

        assert!(!result.submitted);
        assert_eq!(
            result.reason,
            Some(NotificationDispatchReason::BackendError)
        );
    }

    #[test]
    fn provisional_authorization_is_allowed_to_dispatch() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Provisional),
            Arc::clone(&backend),
        );

        assert!(service.dispatch(&agent_request()).submitted);
        assert_eq!(backend.count(), 1);
    }

    #[test]
    fn non_authoritative_unknown_status_still_dispatches() {
        // Windows/Linux report unknown; they must keep working rather than
        // being blocked by the absence of an authoritative query.
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            NotificationPermissionStatusDto::non_authoritative(NotificationPlatform::Linux, false),
            Arc::clone(&backend),
        );

        assert!(service.dispatch(&agent_request()).submitted);
        assert_eq!(backend.count(), 1);
    }

    #[test]
    fn unsupported_platform_rejects_dispatch() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            NotificationPermissionStatusDto::unsupported(NotificationPlatform::Other),
            Arc::clone(&backend),
        );

        let result = service.dispatch(&agent_request());

        assert_eq!(result.reason, Some(NotificationDispatchReason::Unsupported));
        assert_eq!(backend.count(), 0);
    }

    #[test]
    fn dispatched_content_is_sanitized_before_reaching_the_backend() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        service.dispatch(&DispatchNotificationRequest {
            source: NotificationSource::TerminalBell,
            worktree_label: Some("feat/login".into()),
            terminal_title: Some("run\u{1b}[31m\ntest".into()),
            ..Default::default()
        });

        let body = backend.first_body().expect("submitted body");
        assert!(!body.contains('\n'));
        assert!(!body.contains('\u{1b}'));
    }

    #[test]
    fn probe_without_test_reports_ready_and_sends_nothing() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        let probe = service.probe_delivery(false);

        assert_eq!(probe.outcome, NotificationProbeOutcome::Ready);
        assert!(!probe.test_submitted);
        assert_eq!(backend.count(), 0);
    }

    #[test]
    fn probe_with_test_submits_exactly_one_test_notification() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        let probe = service.probe_delivery(true);

        assert_eq!(probe.outcome, NotificationProbeOutcome::Submitted);
        assert!(probe.test_submitted);
        assert_eq!(backend.count(), 1);
        assert_eq!(
            backend.first_title().as_deref(),
            Some("Ferryx notifications are working")
        );
    }

    #[test]
    fn probe_reports_blocked_without_sending_a_test() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::Denied),
            Arc::clone(&backend),
        );

        let probe = service.probe_delivery(true);

        assert_eq!(probe.outcome, NotificationProbeOutcome::BlockedBySystem);
        assert!(!probe.test_submitted);
        assert_eq!(backend.count(), 0);
        // The UI needs this to offer "Open System Settings".
        assert!(probe.status.can_open_settings);
    }

    #[test]
    fn probe_reports_permission_required_without_prompting() {
        let backend = Arc::new(FakeBackend::default());
        let service = service_with(
            macos_status(NotificationAuthorization::NotDetermined),
            Arc::clone(&backend),
        );

        let probe = service.probe_delivery(true);

        assert_eq!(probe.outcome, NotificationProbeOutcome::PermissionRequired);
        assert!(!probe.test_submitted);
        assert_eq!(backend.count(), 0);
    }

    #[test]
    fn probe_failure_reports_failed_not_submitted() {
        let backend = Arc::new(FakeBackend::failing("backend down"));
        let service = service_with(
            macos_status(NotificationAuthorization::Authorized),
            Arc::clone(&backend),
        );

        let probe = service.probe_delivery(true);

        assert_eq!(probe.outcome, NotificationProbeOutcome::Failed);
        assert!(!probe.test_submitted);
    }

    #[test]
    fn preflight_decisions_cover_every_authorization_state() {
        assert_eq!(
            preflight(&macos_status(NotificationAuthorization::Authorized)),
            PreflightDecision::Submit
        );
        assert_eq!(
            preflight(&macos_status(NotificationAuthorization::Provisional)),
            PreflightDecision::Submit
        );
        assert_eq!(
            preflight(&macos_status(NotificationAuthorization::Denied)),
            PreflightDecision::Reject(NotificationDispatchReason::BlockedBySystem)
        );
        assert_eq!(
            preflight(&macos_status(NotificationAuthorization::NotDetermined)),
            PreflightDecision::Reject(NotificationDispatchReason::PermissionRequired)
        );
        assert_eq!(
            preflight(&macos_status(NotificationAuthorization::Unknown)),
            PreflightDecision::Submit
        );
    }

    #[test]
    fn non_authoritative_denied_does_not_block() {
        // A denied value without an authoritative query is a guess and must
        // not silently suppress notifications.
        let mut status = macos_status(NotificationAuthorization::Denied);
        status.authoritative = false;

        assert_eq!(preflight(&status), PreflightDecision::Submit);
    }

    #[test]
    fn explicit_permission_request_reaches_the_provider_once() {
        let provider =
            FakePermissionProvider::new(macos_status(NotificationAuthorization::Authorized));
        let request_calls = Arc::clone(&provider.request_calls);
        let service = NotificationService::new(
            Box::new(provider),
            Box::new(Arc::new(FakeBackend::default())),
        );

        let result = service.request_permission();

        assert!(result.granted);
        assert_eq!(request_calls.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn permission_status_passes_through_the_provider_value() {
        let service = service_with(
            macos_status(NotificationAuthorization::Denied),
            Arc::new(FakeBackend::default()),
        );

        let status = service.permission_status();

        assert_eq!(status.authorization, NotificationAuthorization::Denied);
        assert!(status.is_blocked());
    }
}

//! Notification IPC commands.
//!
//! The frontend never calls `@tauri-apps/plugin-notification` or
//! `plugin-dialog` directly. Every OS interaction goes through these typed
//! commands, which keeps platform differences out of React, gives tests one
//! mockable contract, and avoids granting broad guest plugin capabilities.

use crate::ipc::{run_blocking, IpcError};
use crate::notification::{
    open_system_notification_settings, picked_audio_file, DispatchNotificationRequest,
    DispatchNotificationResult, NativeNotificationBackend, NotificationAudioPlayer,
    NotificationContent, NotificationPermissionRequestDto, NotificationPermissionStatusDto,
    NotificationProbeResult, NotificationService, OpenSystemSettingsResult, PickedAudioFile,
    PlaySoundResult, SUPPORTED_AUDIO_EXTENSIONS,
};
use std::path::PathBuf;
use std::sync::Arc;
use tauri::{AppHandle, Runtime, State};
use tauri_plugin_dialog::DialogExt;
use tauri_plugin_notification::NotificationExt;

/// Native backend built on `tauri-plugin-notification`.
pub struct TauriNotificationBackend<R: Runtime> {
    app: AppHandle<R>,
}

impl<R: Runtime> TauriNotificationBackend<R> {
    pub fn new(app: AppHandle<R>) -> Self {
        Self { app }
    }
}

impl<R: Runtime> NativeNotificationBackend for TauriNotificationBackend<R> {
    fn submit(&self, content: &NotificationContent) -> Result<(), String> {
        self.app
            .notification()
            .builder()
            .title(&content.title)
            .body(&content.body)
            .show()
            .map_err(|error| error.to_string())
    }
}

/// Build a service bound to the running app.
///
/// The permission provider is the authoritative platform one; on macOS that is
/// `UNUserNotificationCenter`, not Tauri's desktop `permission_state()`.
fn service_for<R: Runtime>(app: &AppHandle<R>) -> NotificationService {
    NotificationService::with_platform_permissions(Box::new(TauriNotificationBackend::new(
        app.clone(),
    )))
}

/// Raise one native notification for an application event.
#[tauri::command]
pub async fn cmd_notification_dispatch<R: Runtime>(
    app: AppHandle<R>,
    request: DispatchNotificationRequest,
) -> Result<DispatchNotificationResult, IpcError> {
    run_blocking(move || Ok(service_for(&app).dispatch(&request))).await
}

/// Read the current authoritative permission status.
#[tauri::command]
pub async fn cmd_notification_get_permission_status<R: Runtime>(
    app: AppHandle<R>,
) -> Result<NotificationPermissionStatusDto, IpcError> {
    run_blocking(move || Ok(service_for(&app).permission_status())).await
}

/// Request notification authorization.
///
/// Only ever invoked from an explicit user action (master switch, test
/// notification, or "Allow notifications") - never at startup.
#[tauri::command]
pub async fn cmd_notification_request_permission<R: Runtime>(
    app: AppHandle<R>,
) -> Result<NotificationPermissionRequestDto, IpcError> {
    run_blocking(move || Ok(service_for(&app).request_permission())).await
}

/// Report notification readiness, optionally sending a visible test.
///
/// Never claims a banner was seen: Focus/Do-Not-Disturb suppression is
/// invisible to the application.
#[tauri::command]
pub async fn cmd_notification_probe_delivery<R: Runtime>(
    app: AppHandle<R>,
    send_test: Option<bool>,
) -> Result<NotificationProbeResult, IpcError> {
    let send_test = send_test.unwrap_or(false);
    run_blocking(move || Ok(service_for(&app).probe_delivery(send_test))).await
}

/// Open the OS notification settings page for rorca.
#[tauri::command]
pub async fn cmd_notification_open_system_settings() -> Result<OpenSystemSettingsResult, IpcError> {
    run_blocking(|| Ok(open_system_notification_settings())).await
}

/// Play a custom notification sound.
///
/// A failure here is a structured result rather than an IPC error: the
/// notification itself may already have been delivered successfully.
#[tauri::command]
pub async fn cmd_notification_play_sound(
    player: State<'_, Arc<NotificationAudioPlayer>>,
    path: PathBuf,
    volume: Option<f32>,
    force: Option<bool>,
) -> Result<PlaySoundResult, IpcError> {
    let player = Arc::clone(&player);
    let volume = volume.unwrap_or(100.0);
    let force = force.unwrap_or(false);
    run_blocking(move || Ok(player.play(&path, volume, force))).await
}

/// Pick a custom notification sound through the native file dialog.
///
/// Returns only the path and display name; the file is never read into the
/// WebView, and no general filesystem access is exposed.
#[tauri::command]
pub async fn cmd_notification_pick_audio<R: Runtime>(
    app: AppHandle<R>,
) -> Result<Option<PickedAudioFile>, IpcError> {
    let (tx, rx) = tokio::sync::oneshot::channel();

    app.dialog()
        .file()
        .add_filter("Audio", SUPPORTED_AUDIO_EXTENSIONS)
        .pick_file(move |selected| {
            let _ = tx.send(selected);
        });

    let selected = rx
        .await
        .map_err(|_| IpcError::internal("audio file dialog closed unexpectedly"))?;

    // User cancelled the dialog.
    let Some(selected) = selected else {
        return Ok(None);
    };

    let path = selected
        .into_path()
        .map_err(|error| IpcError::internal(format!("invalid audio selection: {error}")))?;

    Ok(Some(picked_audio_file(path)))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::notification::{
        is_supported_audio_extension, NotificationAuthorization, NotificationDispatchReason,
        NotificationPlatform, NotificationProbeOutcome, NotificationSource, PlaySoundReason,
    };
    use serde_json::json;
    use tauri::Manager;

    /// Mock app managing the same audio state `lib.rs` registers.
    fn mock_app() -> tauri::App<tauri::test::MockRuntime> {
        tauri::test::mock_builder()
            .manage(Arc::new(NotificationAudioPlayer::new()))
            .build(tauri::test::mock_context(tauri::test::noop_assets()))
            .expect("mock app")
    }

    #[tokio::test]
    async fn play_sound_command_reports_missing_file_without_erroring() {
        let app = mock_app();
        let player = app.state::<Arc<NotificationAudioPlayer>>();

        let result = cmd_notification_play_sound(
            player,
            PathBuf::from("/nonexistent/orca-ding.wav"),
            Some(80.0),
            Some(true),
        )
        .await
        .expect("command must resolve, not fail");

        assert!(!result.played);
        assert_eq!(result.reason, Some(PlaySoundReason::NotFound));
    }

    #[tokio::test]
    async fn play_sound_command_rejects_unsupported_formats() {
        let app = mock_app();
        let player = app.state::<Arc<NotificationAudioPlayer>>();
        let dir = tempfile::TempDir::new().expect("tempdir");
        let path = dir.path().join("payload.sh");
        std::fs::write(&path, b"#!/bin/sh\necho nope").expect("write file");

        let result = cmd_notification_play_sound(player, path, Some(50.0), Some(true))
            .await
            .expect("command resolves");

        assert_eq!(result.reason, Some(PlaySoundReason::UnsupportedFormat));
    }

    #[tokio::test]
    async fn play_sound_command_tolerates_omitted_optional_arguments() {
        let app = mock_app();
        let player = app.state::<Arc<NotificationAudioPlayer>>();
        let dir = tempfile::TempDir::new().expect("tempdir");
        let path = dir.path().join("missing.wav");

        let result = cmd_notification_play_sound(player, path, None, None)
            .await
            .expect("command resolves");

        assert!(!result.played);
    }

    #[tokio::test]
    async fn open_system_settings_command_returns_a_structured_result() {
        let result = cmd_notification_open_system_settings()
            .await
            .expect("command resolves");

        #[cfg(not(any(target_os = "macos", target_os = "windows")))]
        {
            assert!(!result.opened);
            assert_eq!(result.reason.as_deref(), Some("unsupported"));
        }
        #[cfg(any(target_os = "macos", target_os = "windows"))]
        {
            // Opening can legitimately fail in a headless session; only the
            // structured shape is guaranteed.
            assert!(result.opened || result.reason.is_some());
        }
    }

    #[test]
    fn dispatch_command_payload_matches_the_frontend_contract() {
        // Mirrors what ui/src/lib/tauri.ts sends through invokeCommand.
        let request: DispatchNotificationRequest = serde_json::from_value(json!({
            "source": "agentTaskComplete",
            "notificationId": "agent-42",
            "workspaceLabel": "orca-lite",
            "worktreeLabel": "orca/ws-1/feat-login",
            "terminalTitle": "claude",
            "agentLabel": "Claude",
        }))
        .expect("payload parses");

        assert_eq!(request.source, NotificationSource::AgentTaskComplete);
        assert_eq!(request.agent_label.as_deref(), Some("Claude"));
        assert_eq!(request.notification_id.as_deref(), Some("agent-42"));
    }

    #[test]
    fn dispatch_result_round_trips_across_the_ipc_boundary() {
        let result =
            DispatchNotificationResult::rejected(NotificationDispatchReason::PermissionRequired);

        let encoded = serde_json::to_string(&result).expect("encode");
        let decoded: DispatchNotificationResult = serde_json::from_str(&encoded).expect("decode");

        assert_eq!(decoded, result);
    }

    #[test]
    fn permission_status_round_trips_across_the_ipc_boundary() {
        let status = NotificationPermissionStatusDto {
            platform: NotificationPlatform::Macos,
            supported: true,
            authorization: NotificationAuthorization::Denied,
            alerts_enabled: Some(false),
            sounds_enabled: Some(true),
            requested: true,
            authoritative: true,
            can_open_settings: true,
        };

        let encoded = serde_json::to_string(&status).expect("encode");
        let decoded: NotificationPermissionStatusDto =
            serde_json::from_str(&encoded).expect("decode");

        assert_eq!(decoded, status);
        assert!(decoded.is_blocked());
    }

    #[test]
    fn permission_request_result_round_trips_across_the_ipc_boundary() {
        let dto = NotificationPermissionRequestDto {
            granted: false,
            status: NotificationPermissionStatusDto::non_authoritative(
                NotificationPlatform::Windows,
                true,
            ),
            error: Some("authorization request timed out".into()),
        };

        let encoded = serde_json::to_string(&dto).expect("encode");
        let decoded: NotificationPermissionRequestDto =
            serde_json::from_str(&encoded).expect("decode");

        assert_eq!(decoded, dto);
    }

    #[test]
    fn probe_result_round_trips_across_the_ipc_boundary() {
        let probe = NotificationProbeResult {
            outcome: NotificationProbeOutcome::Submitted,
            status: NotificationPermissionStatusDto::non_authoritative(
                NotificationPlatform::Linux,
                false,
            ),
            test_submitted: true,
        };

        let encoded = serde_json::to_string(&probe).expect("encode");
        let decoded: NotificationProbeResult = serde_json::from_str(&encoded).expect("decode");

        assert_eq!(decoded, probe);
    }

    #[test]
    fn picked_audio_result_round_trips_including_cancellation() {
        let cancelled: Option<PickedAudioFile> =
            serde_json::from_str("null").expect("null decodes as cancellation");
        assert!(cancelled.is_none());

        let picked = Some(picked_audio_file(PathBuf::from("/tmp/ding.wav")));
        let encoded = serde_json::to_string(&picked).expect("encode");
        let decoded: Option<PickedAudioFile> = serde_json::from_str(&encoded).expect("decode");

        assert_eq!(decoded, picked);
    }

    #[test]
    fn picker_filters_only_offer_decodable_formats() {
        // The dialog filter must not advertise formats rodio cannot decode.
        for extension in SUPPORTED_AUDIO_EXTENSIONS {
            assert!(
                is_supported_audio_extension(std::path::Path::new(&format!("sound.{extension}"))),
                "picker filter offers undecodable extension: {extension}"
            );
        }
    }
}

