+pub fn format_badge_label(count: u32) -> Option<String> {
+    if count == 0 {
+        None
+    } else {
+        Some(count.to_string())
+    }
+}
+
+/// Set the application badge count on the host platform.
+pub fn set_application_badge_count(count: u32) -> SetBadgeCountResult {
+    let label = format_badge_label(count);
+
+    #[cfg(target_os = "macos")]
+    {
+        macos::set_dock_badge_label(label.as_deref());
+        SetBadgeCountResult::macos(count, label)
+    }
+
+    #[cfg(not(target_os = "macos"))]
+    {
+        SetBadgeCountResult::unsupported(count)
+    }
+}
+
+#[cfg(target_os = "macos")]
+pub mod macos {
+    use objc2::MainThreadMarker;
+    use objc2_app_kit::NSApplication;
+    use objc2_foundation::NSString;
+
+    pub fn set_dock_badge_label(label: Option<&str>) {
+        let label_ns = label.map(NSString::from_str);
+
+        let _ = objc2::exception::catch(std::panic::AssertUnwindSafe(|| {
+            if let Some(mtm) = MainThreadMarker::new() {
+                let app = NSApplication::sharedApplication(mtm);
+                let dock_tile = app.dockTile();
+                dock_tile.setBadgeLabel(label_ns.as_deref());
+            } else {
+                MainThreadMarker::run_on_main(|mtm| {
+                    let app = NSApplication::sharedApplication(mtm);
+                    let dock_tile = app.dockTile();
+                    dock_tile.setBadgeLabel(label_ns.as_deref());
+                });
+            }
+        }));
+    }
+}

