+    pub fn handle_register_workspace(
+        &self,
+        workspace_id: &str,
+        repo_root: &str,
+    ) -> Result<(), String> {
+        let path = PathBuf::from(repo_root);
+        let canonical = fs::canonicalize(&path)
+            .map_err(|e| format!("Invalid repo_root path '{}': {e}", path.display()))?;
+        if !canonical.is_dir() {
+            return Err(format!(
+                "Repo root '{}' is not a directory",
+                canonical.display()
+            ));
+        }
+        self.workspace_registry
+            .register(workspace_id, &canonical)
+            .map_err(|e| e.to_string())
+    }
+
+    pub async fn handle_remote_configure(
+        &self,
+        config: RemoteGatewayConfig,
+    ) -> Result<(), String> {
+        *self.remote_state.config.write() = config.clone();
+
+        // Stop current running server if any
+        let prev_handle = self.remote_server_handle.lock().take();
+        if let Some(handle) = prev_handle {
+            handle.stop();
+        }
+
+        match config.mode {
+            RemoteNetworkMode::Off => Ok(()),
+            _ => {
+                let (handle, _) = start_remote_server(Arc::clone(&self.remote_state)).await?;
+                *self.remote_server_handle.lock() = Some(handle);
+                Ok(())
+            }
         }
     }

