//! Application badge domain logic and native Dock tile updates.
//!
//! Exposes typed badge count synchronization for the macOS Dock tile.
//! On non-macOS platforms, operations return a structured unsupported outcome
//! without failing. Never accepts arbitrary user-controlled strings over IPC.

use serde::{Deserialize, Serialize};

/// Structured result of an application badge count update.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SetBadgeCountResult {
    pub supported: bool,
    pub count: u32,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub badge_label: Option<String>,
}

impl SetBadgeCountResult {
    pub fn macos(count: u32, badge_label: Option<String>) -> Self {
        Self {
            supported: true,
            count,
            badge_label,
        }
    }

    pub fn unsupported(count: u32) -> Self {
        Self {
            supported: false,
            count,
            badge_label: None,
        }
    }
}

/// Format an unread count into an application badge label.
///
/// Returns `Some(decimal_string)` when count > 0, and `None` when count == 0.
pub fn format_badge_label(count: u32) -> Option<String> {
    if count == 0 {
        None
    } else {
        Some(count.to_string())
    }
}

/// Set the application badge count on the host platform.
pub fn set_application_badge_count(count: u32) -> SetBadgeCountResult {
    let label = format_badge_label(count);

    #[cfg(target_os = "macos")]
    {
        macos_impl::set_dock_badge_label(label.as_deref());
        SetBadgeCountResult::macos(count, label)
    }

    #[cfg(not(target_os = "macos"))]
    {
        SetBadgeCountResult::unsupported(count)
    }
}

#[cfg(target_os = "macos")]
mod macos_impl {
    use objc2::MainThreadMarker;
    use objc2_app_kit::NSApplication;
    use objc2_foundation::NSString;

    pub fn set_dock_badge_label(label: Option<&str>) {
        let label_ns = label.map(NSString::from_str);

        let _ = objc2::exception::catch(std::panic::AssertUnwindSafe(|| {
            // SAFETY: In AppKit, NSApplication::sharedApplication returns the process
            // singleton, and `-[NSDockTile setBadgeLabel:]` is thread-safe and updates
            // the application Dock tile asynchronously across threads.
            let mtm = unsafe { MainThreadMarker::new_unchecked() };
            let app = NSApplication::sharedApplication(mtm);
            let dock_tile = app.dockTile();
            dock_tile.setBadgeLabel(label_ns.as_deref());
        }));
    }
}

