                );
            }
        }
    }
    #[cfg(not(target_os = "macos"))]
    {
        let outcome = result.expect("command resolves on non-macos as unsupported no-op");
        assert!(!outcome.supported);
        assert_eq!(outcome.count, 0);
        assert!(outcome.badge_label.is_none());
    }
}

